import{_ as e,H as t,f as a,i as r}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/best-practices.md","filePath":"zh/guide/best-practices.md"}'),n={name:"zh/guide/best-practices.md"};function i(s,o,d,c,l,p){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h1><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><p><strong>声明式写，不要叙述式。</strong> 用 <code>contract:</code>、<code>invariant:</code>、<code>test:</code>、<code>failure:</code> 这样的章节，不要编号步骤或散文。智能体读得快，跟随精确的声明。</p><p><strong>仅关闭影响实现的决策。</strong> 在移交 <code>plan</code> 前，解决：契约、数据形状、失败模式、测试标准。把哲学争论和&quot;锦上添花&quot;留在 <code>deferred</code> 或 <code>Working notes</code>。</p><p><strong>按路径引用代码，永不粘贴。</strong> 规范是关于要构建什么的决策，不是怎样构建的演走。</p><h2 id="计划" tabindex="-1">计划 <a class="header-anchor" href="#计划" aria-label="Permalink to &quot;计划&quot;">​</a></h2><p><strong>任务是 30-60 分钟</strong> 原子化到智能体能推理它们。太大了你失去可见性；太小了失去速度。</p><p><strong>Acceptance 可执行。</strong> 每个任务的验收条件必须是 CI/人类能验证的东西：测试名、命令或脚本。不模糊，不好高骛远。</p><p><strong>标记 <code>[parallel]</code> 仅当真正独立。</strong> 共享状态、错误处理或未闭合的契约 → 任务不并行。过度标记导致破坏的合并。</p><h2 id="git-工作流" tabindex="-1">Git 工作流 <a class="header-anchor" href="#git-工作流" aria-label="Permalink to &quot;Git 工作流&quot;">​</a></h2><p><strong>每个 RED-GREEN-refactor 循环一次提交。</strong> 把你的思考推进历史。后来调试时有帮助。</p><p><strong>每个循环后同步文档。</strong> 就在提交前。如果你等待，你会忘记你改了什么和为什么。</p><p><strong>用描述性分支名。</strong> <code>feat/oauth-github</code>，不是 <code>feature1</code>。当你有多个 worktree 时帮你导航。</p><h2 id="大型项目" tabindex="-1">大型项目 <a class="header-anchor" href="#大型项目" aria-label="Permalink to &quot;大型项目&quot;">​</a></h2><p><strong>当 ≥3 个里程碑时用 roadmap。</strong> 不要试着一次性计划他们。<code>plan</code> 仅当前的，随着你学习更新 stub。</p><p><strong>清晰标记当前里程碑。</strong> <code>← 现在详细计划</code> 在 M1 上信号意图。在计划 M2 前，ship 后移动标记。</p><p><strong>期望在 M1 后修改里程碑。</strong> 第一个里程碑教你剩下的会花费多少。那是要点。</p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p><strong>隔离优先，假设其次。</strong> 缩小到最小重现。删除代码直到症状消失。仅然后问&quot;为什么&quot;。</p><p><strong>每次改一个变量。</strong> 并行很诱人但让很难知道哪个改变修复了它。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><strong>测试契约，不是实现。</strong> 如果契约说&quot;成功时返回 200&quot;，就测试这。不是&quot;调用 X 函数&quot;或&quot;从数据库 Y 读取&quot;。</p><p><strong>无内部的 mock。</strong> Mock 外部边界：HTTP、DB、文件系统。Mock 你自己的代码仅当真实版本很慢或非确定性。</p><h2 id="何时放弃" tabindex="-1">何时放弃 <a class="header-anchor" href="#何时放弃" aria-label="Permalink to &quot;何时放弃&quot;">​</a></h2><p><strong>如果假设实质改变，停止并重新探索。</strong> 不要强行通过如果你在解决的问题不再是问题了。在探索笔记中标记出尝试后得到的原因和经验。</p><h2 id="规范评审合成-spec-review-synthesis" tabindex="-1">规范评审合成 (Spec Review Synthesis) <a class="header-anchor" href="#规范评审合成-spec-review-synthesis" aria-label="Permalink to &quot;规范评审合成 (Spec Review Synthesis)&quot;">​</a></h2><p><strong>评审员建议，Coordinator 裁决。</strong> 规范评审员作为独立 Subagent 按照特定契约运行。主智能体（Coordinator）对审查结果进行批判性评估，解决冲突、补齐遗漏边界，并一次性修补规范，而不是被动堆砌 Subagent 输出。</p><h2 id="模型分级映射-model-tier-mapping" tabindex="-1">模型分级映射 (Model Tier Mapping) <a class="header-anchor" href="#模型分级映射-model-tier-mapping" aria-label="Permalink to &quot;模型分级映射 (Model Tier Mapping)&quot;">​</a></h2><p><strong>根据任务风险匹配模型能力。</strong> 将 <code>fast</code> 用于机械化修改或 Lint 检查，<code>balanced</code> 用于单组件实现，<code>strongest</code> 用于核心协议、安全评审或复杂状态机。在 <code>.praxis/model-tiers.yaml</code> 中配置这些分级。</p><h2 id="多模块协同-multi-module-coordination" tabindex="-1">多模块协同 (Multi-Module Coordination) <a class="header-anchor" href="#多模块协同-multi-module-coordination" aria-label="Permalink to &quot;多模块协同 (Multi-Module Coordination)&quot;">​</a></h2><p><strong>明确指定一个 Coordinator 仓库。</strong> Coordinator 持有 change-set ID、跨模块规范及工作区计划。严禁在各模块规范中重复定义共享契约；统一引用 Coordinator 规范。提交修改时按依赖顺序执行，Coordinator 仓库最后提交。</p><h2 id="文档同步" tabindex="-1">文档同步 <a class="header-anchor" href="#文档同步" aria-label="Permalink to &quot;文档同步&quot;">​</a></h2><p><strong>Living docs 是事实，staging docs 是草稿。</strong> <code>ship</code> 后，规范移到 living docs。代码中的测试和注释与两者保持当前。</p><p><strong>README 是第一个规范。</strong> 如果它不匹配代码，PR 失败评审。同样规则适用于所有公共契约。</p>',34)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
